// ---- Shared helpers (same block in every FS Code node) ----
const str = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const truthy = (v) => v === true || ['TRUE', 'YES', 'Y', '1'].includes(str(v).toUpperCase());
const FIELD_TYPES = ['text', 'longtext', 'email', 'phone', 'number', 'date', 'dropdown', 'checkbox'];

function normalizeEvents(rows) {
  return rows
    .filter((r) => str(r.event_id))
    .map((r) => ({
      event_id: str(r.event_id),
      event_name: str(r.event_name) || str(r.event_id),
      target_tab: str(r.target_tab) || ('Data_' + str(r.event_id)),
      is_default: truthy(r.is_default),
      // a blank "active" cell counts as active
      active: str(r.active) === '' ? true : truthy(r.active),
    }));
}

function normalizeFields(rows, eventId) {
  const seen = new Set();
  return rows
    .filter((r) => str(r.event_id) === eventId && str(r.field_key))
    .map((r, i) => {
      const type = str(r.field_type).toLowerCase();
      const order = Number(str(r.order));
      return {
        key: str(r.field_key),
        label: str(r.form_label) || str(r.field_key),
        type: FIELD_TYPES.includes(type) ? type : 'text',
        required: truthy(r.required),
        options: str(r.options).split(/[,|]/).map((o) => o.trim()).filter(Boolean),
        hint: str(r.ai_hint),
        order: Number.isFinite(order) && str(r.order) !== '' ? order : 1000 + i,
      };
    })
    .sort((a, b) => a.order - b.order)
    .filter((f) => (seen.has(f.key) ? false : seen.add(f.key)));
}

// Normalizes a single value to the format that gets stored in the sheet.
function cleanValue(field, value) {
  let v = str(value);
  switch (field.type) {
    case 'email':
      return v.replace(/\s+/g, '').toLowerCase();
    case 'phone':
      return v.replace(/[^\d+]/g, '');
    case 'checkbox':
      return v === '' ? '' : (truthy(v) || ['CHECKED', 'X', '✓', '✔'].includes(v.toUpperCase()) ? 'TRUE' : 'FALSE');
    case 'dropdown': {
      const match = field.options.find((o) => o.toLowerCase() === v.toLowerCase());
      return match || v;
    }
    default:
      return v;
  }
}
// ---- End shared helpers ----

// Validates the upload and builds the Gemini request from the event's field mapping.
// Change the model here. "gemini-flash-latest" always points to Google's current Flash model.
const MODEL = 'gemini-flash-latest';
const MAX_BASE64_CHARS = 10 * 1024 * 1024; // ~7.5 MB image

const fail = (error) => [{ json: { ok: false, error } }];

const body = $('Webhook').first().json.body || {};
const eventId = str(body.event_id);
let image = str(body.image);
let mime = str(body.mime) || 'image/jpeg';

const dataUrl = image.match(/^data:([^;]+);base64,([\s\S]*)$/);
if (dataUrl) { mime = dataUrl[1]; image = dataUrl[2]; }
image = image.replace(/\s+/g, '');

if (!eventId) return fail('No event selected.');
if (!image) return fail('No image received.');
if (image.length > MAX_BASE64_CHARS) return fail('Image is too large. Please retake the photo.');
if (!/^image\/(jpeg|png|webp|heic|heif)$/i.test(mime)) return fail(`Unsupported image type: ${mime}`);

const event = normalizeEvents($('Read Events').all().map((i) => i.json)).find((e) => e.event_id === eventId);
if (!event || !event.active) return fail(`Event ${eventId} was not found or is inactive.`);

const fields = normalizeFields($('Read Fields').all().map((i) => i.json), eventId);
if (!fields.length) return fail(`Event ${eventId} has no field mapping.`);

const fieldLines = fields.map((f) => {
  const parts = [`label on the form: "${f.label}"`, `type: ${f.type}`];
  if (f.type === 'dropdown' && f.options.length) parts.push(`allowed values: ${f.options.join(' | ')}`);
  if (f.type === 'checkbox') parts.push('answer TRUE if ticked/marked, FALSE if not');
  if (f.type === 'date') parts.push('format YYYY-MM-DD');
  if (f.hint) parts.push(`hint: ${f.hint}`);
  return `- ${f.key} (${parts.join('; ')})`;
}).join('\n');

const prompt = [
  'You are a careful data-entry assistant. The image is a photo of a filled-in paper form.',
  `Event: ${event.event_name}`,
  '',
  'Extract the value written for each field below. Each line gives the JSON key, then the label printed on the form.',
  fieldLines,
  '',
  'Rules:',
  '- Return only the JSON keys listed above, plus "uncertain_fields".',
  '- Copy what is written. Do not guess, invent, or fill in missing parts.',
  '- If a field is blank, crossed out, or unreadable, return an empty string "".',
  '- For fields with allowed values, return one of them exactly, or "" if none matches.',
  '- "uncertain_fields" must list the keys of any value you are not confident about (e.g. unclear handwriting).',
].join('\n');

const properties = {};
for (const f of fields) {
  properties[f.key] = { type: 'STRING', description: f.label + (f.hint ? ` (${f.hint})` : '') };
}
properties.uncertain_fields = { type: 'ARRAY', items: { type: 'STRING' } };
const keys = fields.map((f) => f.key);

return [{
  json: {
    ok: true,
    event_id: eventId,
    model: MODEL,
    url: `https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent`,
    fields,
    request: {
      contents: [{
        role: 'user',
        parts: [
          { text: prompt },
          { inlineData: { mimeType: mime, data: image } },
        ],
      }],
      generationConfig: {
        temperature: 0,
        responseMimeType: 'application/json',
        responseSchema: {
          type: 'OBJECT',
          properties,
          required: [...keys, 'uncertain_fields'],
          propertyOrdering: [...keys, 'uncertain_fields'],
        },
      },
    },
  },
}];

