}
// ---- End shared helpers ----

// Turns Gemini's reply into clean values for the review form.
const built = $('Build Gemini Request').first().json;
const fields = built.fields;
const res = $input.first().json || {};

const fail = (error) => [{ json: { ok: false, error } }];

if (res.error) {
  const e = res.error;
  const msg = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e));
  return fail('AI request failed: ' + str(msg).slice(0, 300));
}

const candidate = (res.candidates || [])[0];
if (!candidate) {
  const reason = res.promptFeedback && res.promptFeedback.blockReason;
  return fail(reason ? `The AI refused the image (${reason}).` : 'The AI returned no result. Please try again.');
}

const text = ((candidate.content && candidate.content.parts) || []).map((p) => p.text || '').join('').trim();
let raw;
try {
  const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  raw = JSON.parse(start >= 0 && end > start ? cleaned.slice(start, end + 1) : cleaned);
} catch (err) {
  return fail('Could not read the AI response. Please try again.');
}

const values = {};
const uncertain = new Set(
  (Array.isArray(raw.uncertain_fields) ? raw.uncertain_fields : []).map(str),
);

for (const f of fields) {
  const original = str(raw[f.key]);
  const v = cleanValue(f, original);
  values[f.key] = v;
  if (f.required && !v) uncertain.add(f.key);
  if (f.type === 'dropdown' && v && f.options.length && !f.options.includes(v)) uncertain.add(f.key);
  if (f.type === 'email' && v && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)) uncertain.add(f.key);
}

return [{
  json: {
    ok: true,
    event_id: built.event_id,
    values,
    uncertain_fields: fields.map((f) => f.key).filter((k) => uncertain.has(k)),
    model: built.model,
    tokens: (res.usageMetadata && res.usageMetadata.totalTokenCount) || null,
  },
}];
